function totalOpenInterest(debts, sprintsSinceTaken) {
  return debts.reduce((sum, d, i) => (
    d.status === 'Open' ? sum + d.interestPerSprint * sprintsSinceTaken[i] : sum
  ), 0);
}

module.exports = { totalOpenInterest };

