function classifyDebt(wasChosenOnPurpose, hasRepaymentPlan) {
  const first = wasChosenOnPurpose ? 'deliberate' : 'inadvertent';
  const second = hasRepaymentPlan ? 'prudent' : 'reckless';
  return `${first}-${second}`;
}

