function overpaidByWaiting(principal, interestPerSprint, forcedDeadlineSprint) {
  const interestAtDeadline = interestPerSprint * forcedDeadlineSprint;
  return Math.max(0, interestAtDeadline - principal);
}

module.exports = { overpaidByWaiting };

