items.solution:
function recommendedRepaySprint(principal, interestPerSprint, forcedDeadlineSprint) {
  const breakEven = Math.ceil(principal / interestPerSprint);
  return Math.min(breakEven, forcedDeadlineSprint);
}

module.exports = { recommendedRepaySprint };
